function wordSearch(board, word) {
  for (let i = 0; i < board.length; i++) {
    for (let j = 0; j < board[i].length; j++) {
      if (board[i][j] === word[0]) {
        if (checkDirection(board, word, i, j, 0, 1) || checkDirection(board, word, i, j, 1, 0)) return true;
      }
    }
  }
  return false;
}
function checkDirection(board, word, row, col, dr, dc) {
  for (let k = 0; k < word.length; k++) {
    const r = row + dr * k, c = col + dc * k;
    if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] !== word[k]) return false;
  }
  return true;
}
